private def ended(a: AgentsControllers, id: String): JobInfo =
    awaitTrue(s"job $id")(
      Transactor(ds).read(JobRepo.get(id)).exists(j => JobState.parse(j.status).exists(_.isTerminal)) &&
        !a.acquireRecheck.jobRunning
    )

