@annotation.tailrec
  private def until(url: String, jid: String, n: Int)(p: JobInfo => Boolean): JobInfo =
    val j = job(url, jid)
    if p(j) || n <= 0 then j else { Thread.sleep(50); until(url, jid, n - 1)(p) }

def job(body: String): JobInfo =
        val (js, jb) = post(s"$url/api/media/import/job", body)
        assertEquals(js, 202, jb)
        val id = decode[JobInfo](jb).fold(e => fail(s"$e: $jb"), identity).id
        @annotation.tailrec

@annotation.tailrec
        def until(n: Int): JobInfo =
